    pub data: T,
    pub status: reqwest::StatusCode,
    pub headers: reqwest::header::HeaderMap,
}

pub struct RequestBuilder<'a, Q, B, T> {
    client: &'a Steel,
    method: reqwest::Method,
    path: String,
    query: Option<Q>,
    body: Option<B>,
    options: RequestOptions,
    _marker: std::marker::PhantomData<fn() -> T>,
}

impl<'a, Q, B, T> RequestBuilder<'a, Q, B, T> {
    request_options_setters! {}
}

impl<'a, Q, B, T> RequestBuilder<'a, Q, B, T>
where
    Q: Serialize,
    B: Serialize,
    T: DeserializeOwned,
{
    pub async fn send(self) -> Result<T, Error> {
        self.client
            .request_with(
                self.method,
                &self.path,
                self.query.as_ref(),
                self.body.as_ref(),
                &self.options,
            )
            .await
    }

    pub async fn raw(self) -> Result<reqwest::Response, Error> {
        self.client
            .send_request(
                self.method,
                &self.path,
                self.query.as_ref(),
                self.body.as_ref(),
                &self.options,
            )
            .await
    }

    pub async fn with_response(self) -> Result<Response<T>, Error> {
        let response = self
            .client
            .send_request(
                self.method,
                &self.path,
                self.query.as_ref(),
                self.body.as_ref(),
                &self.options,
            )
            .await?;
        let status = response.status();
        let headers = response.headers().clone();
        let data = decode_body::<T>(&response.bytes().await?)?;
        Ok(Response {
            data,
            status,
            headers,
        })
    }
}

